import sys, json
events = {}
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        obj = json.loads(line)
        ev = obj.get('event', '?')
        events[ev] = events.get(ev, 0) + 1
    except:
        pass
for k in sorted(events):
    print(f'  {k}: {events[k]} occurrences')
"
